{
  "authority": {
    "sealedRowsApplied": [],
    "sealedRowsReviewedButNotApplied": [
      {
        "row": "D08",
        "decisionId": "T68-D07-EVALUATION-DECAY",
        "reason": "Decision-record row D08 is a D07 relation-evaluation subdecision; its domain and consequences do not touch D08 family formation or effect lifecycle."
      },
      {
        "row": "D17",
        "decisionId": "GP-07",
        "reason": "Title ratification authorship is owned by D10/D09 and does not choose a D08 marriage or adoption rule."
      },
      {
        "row": "D21",
        "decisionId": "T68-PF-02",
        "reason": "Organization values do not define D08 eligibility, consent, formation or lineage."
      }
    ],
    "priorApprovedRules": [
      "registered and authorized forum law handles a family action",
      "marriage consent is recorded directly by the parties when the forum law permits that route",
      "adoption requires valid consent from the named adoptive parent and adoptee, while the full procedure remains held",
      "joint property requires a separate signed contract from every current owner for each asset",
      "consent, ratification and effect attribution are separate ledger records and do not themselves form a marriage",
      "formed marriage alone creates neither a new claim nor territory",
      "alliance, property, ratification and heir effects are evaluated separately on death, detention or office loss",
      "body, office, title and property succession are separate events",
      "a recognized synthetic person is not transferable property",
      "affiliation, relationship, movement and office ratification require separate cause events",
      "stable IDs, explicit revision conflicts and at-most-once result application"
    ],
    "symbolicFamilyContract": {
      "path": "/Volumes/gameWorkspace/worktrees/seoul-kenshi/seoul-domain-source-falsification-20261004/.omo/evidence/mechanisms/owner-family-selected-contract-20261005/selected-contract.json",
      "verificationVerdict": "confirmedFamilyEstateOwnerSelectedContractOnly",
      "selectionsUsed": [
        "country-law-A",
        "marriage-consent-A",
        "adoption-consent-A",
        "joint-property-A"
      ],
      "boundary": "These selections approve symbolic operators only. Actual faction laws, ages, eligibility, adoption procedure, shares, durations and coefficients remain proposals."
    },
    "gurpsLikeBasis": {
      "classification": "not-applicable-to-D08-calculation",
      "anchors": [],
      "statement": "D08 has no GURPS-LIKE numeric calculation. The public Lite basis is reviewed only to confirm no personal-roll or CP mechanic is imported into family formation.",
      "noGurps2004Claim": true
    },
    "noNewOwnerDecisions": true
  },
  "sourceComparisons": {
    "ck3": "Guarded prestige/piety/fertility expressions and betrothal writers are documentary comparison only. No cost, threshold, immediate execution or procedure is adopted.",
    "norland": "Documented relationship guards, migration/gold/relationship effects and historical timers are comparison only. Conflicting historical thresholds and native timing remain non-Seoul values."
  },
  "workedExamples": [
    {
      "id": "cross-state-records-unknown-forum",
      "kind": "normal-boundary",
      "input": {
        "participants": [
          "A",
          "B"
        ],
        "consents": [
          "A",
          "B"
        ],
        "ratifications": [
          "R1"
        ],
        "forum": {
          "registered": null,
          "authorized": null,
          "routePermitted": null
        }
      },
      "work": "Two consent records plus one ratification record give three attributed records. Unknown forum prevents adjudication; no claim/territory conclusion is written.",
      "expected": {
        "recordCount": 3,
        "formation": "undetermined-law",
        "newClaimCount": null,
        "territoryTransferCount": null
      },
      "valueStatus": "illustrative identities; no balance values"
    },
    {
      "id": "formed-marriage-no-automatic-right",
      "kind": "normal",
      "input": {
        "forum": {
          "registered": true,
          "authorized": true,
          "routePermitted": true
        },
        "adjudication": "formed",
        "preexistingClaims": [
          "C-old"
        ]
      },
      "work": "Attributed forum result forms the marriage. Marriage formation writes zero new claims and zero territory transfers while retaining C-old.",
      "expected": {
        "formation": "formed",
        "claims": [
          "C-old"
        ],
        "newClaimCount": 0,
        "territoryTransferCount": 0
      },
      "valueStatus": "zero is a cause-specific approved invariant, not a balance coefficient"
    },
    {
      "id": "office-loss-effect-split",
      "kind": "boundary",
      "input": {
        "formation": "formed",
        "trigger": "office-loss",
        "officeEffective": true,
        "effectOutcomes": {
          "alliance": "kept",
          "property": "undetermined",
          "ratification": "reratification-required",
          "heir": "kept"
        }
      },
      "work": "Office authority stops. Four effect outcomes remain separate; unknown property does not erase the other outcomes or dissolve the marriage.",
      "expected": {
        "officeEffective": false,
        "marriageFormation": "formed",
        "effects": {
          "alliance": "kept",
          "property": "undetermined",
          "ratification": "reratification-required",
          "heir": "kept"
        }
      },
      "valueStatus": "symbolic effect fixture"
    },
    {
      "id": "adoption-consent-without-procedure",
      "kind": "failure-boundary",
      "input": {
        "adoptiveParent": "P",
        "adoptee": "C",
        "consents": [
          "P",
          "C"
        ],
        "procedureRegistered": false
      },
      "work": "Both named participant consents satisfy the selected consent direction, but no approved procedure exists; records remain and formation is undetermined.",
      "expected": {
        "recordCount": 2,
        "adoption": "undetermined-procedure"
      },
      "valueStatus": "illustrative identities"
    },
    {
      "id": "synthetic-person-property-rejection",
      "kind": "failure",
      "input": {
        "assetId": "SYN-1",
        "syntheticPersonRecognized": true
      },
      "work": "Recognized personhood excludes the entity from transferable assets in every family branch.",
      "expected": {
        "error": "E_PERSON_NOT_PROPERTY"
      },
      "valueStatus": "predicate fixture"
    }
  ]
}
